namespace ghidra.app.plugin.core.decompile.actions;

using docking;
using docking.action;
using ghidra.app.actions;
using ghidra.app.context;
using ghidra.app.plugin.core.decompile;
using ghidra.app.plugin.core.navigation.locationreferences;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.util;

/**
 * An action to show all references to the given address
 */
public class FindReferencesToAddressAction : AbstractFindReferencesToAddressAction {

	public FindReferencesToAddressAction(PluginTool tool, string owner) : base(tool, owner)
    {

		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionShowReferences"));
		setPopupMenuData(new MenuData(new string[] { LocationReferencesService.MENU_GROUP, NAME }));
	}

	/* @Override */
	protected bool isMyNavigatable(NavigatableActionContext context) {
		return context is DecompilerActionContext;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DecompilerActionContext dac)) {
			return false;
		}

		Address address = dac.getAddress();
		if (address == null) {
			return false;
		}
		updateMenuName(address);
		return base.isEnabledForContext(context);
	}

	private void updateMenuName(Address addr) {
		string menuName = "Find References to " + addr.toString();
		MenuData data = getPopupMenuData().cloneData();
		data.setMenuPath(new string[] { LocationReferencesService.MENU_GROUP, menuName });
		setPopupMenuData(data);
	}
}
